<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">COPY</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> --from=build /usr/bin/dumb-init /usr/bin/dumb-init</span></span>
